    if (typeof metric.averageDelta === 'number') {
      lines.push(`- **Average Delta:** ${metric.averageDelta}`);
    }
    lines.push('');
  });
  lines.push('---');
  lines.push('*Generated by FRAI Evaluation Harness*');
  return lines.join('\n');
}

