142	export function validateGovernancePlan(plan) {
143	  const errors = [];
144	
145	  if (!isPlainObject(plan)) {
146	    return {
147	      valid: false,
148	      errors: [{ path: '', message: 'Governance plan must be an object.' }]
149	    };
150	  }
151	
152	  for (const [sectionName, sectionDef] of Object.entries(GOVERNANCE_SECTIONS)) {
153	    const section = ensureSection(plan, sectionName, errors);
154	    if (!isPlainObject(section)) continue;
155	
156	    for (const requiredField of sectionDef.requiredFields) {
157	      if (section[requiredField] === undefined || section[requiredField] === null) {
158	        errors.push({
159	          path: `${sectionName}.${requiredField}`,
160	          message: `Field "${requiredField}" is required in section "${sectionName}".`
161	        });
162	      }
163	    }
164	
165	    for (const [fieldName, expectedShape] of Object.entries(sectionDef.fieldShapes)) {
166	      const value = section[fieldName];
167	      if (value === undefined || value === null) continue;
168	      if (!validateFieldShape(value, expectedShape)) {
169	        errors.push({
170	          path: `${sectionName}.${fieldName}`,
171	          message: `Field "${fieldName}" in section "${sectionName}" must match shape "${expectedShape}".`
172	        });
173	      }
174	    }
175	  }
176	
177	  const dataset = plan.dataset ?? {};
178	  if (dataset.sensitivity) {
179	    if (!DATA_SENSITIVITY_LEVELS.includes(dataset.sensitivity.level)) {
180	      errors.push({
181	        path: 'dataset.sensitivity.level',
182	        message: `Sensitivity level must be one of: ${DATA_SENSITIVITY_LEVELS.join(', ')}.`
183	      });
184	    }
185	    if (typeof dataset.sensitivity.piiPresent !== 'boolean') {
186	      errors.push({
187	        path: 'dataset.sensitivity.piiPresent',
188	        message: 'PII presence flag must be a boolean.'
189	      });
190	    }
191	  }
192	
193	  if (dataset.sources) {
194	    errors.push(...validateDatasetSources(asArray(dataset.sources)));
195	  }
196	
197	  const training = plan.training ?? {};
198	  if (training.safety && Array.isArray(training.safety.guardrails)) {
199	    if (!training.safety.guardrails.every(hasStringValue)) {
200	      errors.push({
201	        path: 'training.safety.guardrails',
202	        message: 'All safety guardrails must be non-empty strings.'
203	      });
204	    }
205	  }
206	
207	  const evaluation = plan.evaluation ?? {};
208	  if (evaluation.metrics) {
209	    errors.push(...validateEvaluationMetrics(asArray(evaluation.metrics)));
210	  }
211	  if (evaluation.gateCriteria) {
212	    if (!RISK_LEVELS.includes(evaluation.gateCriteria.riskTolerance)) {
213	      errors.push({
214	        path: 'evaluation.gateCriteria.riskTolerance',
215	        message: `Risk tolerance must be one of: ${RISK_LEVELS.join(', ')}.`
216	      });
217	    }
218	    if (typeof evaluation.gateCriteria.minimumSuccessRate !== 'number') {
219	      errors.push({
220	        path: 'evaluation.gateCriteria.minimumSuccessRate',
221	        message: 'Minimum success rate must be numeric.'
222	      });
223	    }
224	  }
225	
226	  const approvals = plan.approvals ?? {};
227	  if (Array.isArray(approvals.stakeholders)) {
228	    errors.push(...validateStakeholders(approvals.stakeholders));
229	  } else {
230	    errors.push({
231	      path: 'approvals.stakeholders',
232	      message: 'Stakeholders must be provided as an array.'
233	    });
234	  }
235	
236	  const monitoring = plan.monitoring ?? {};
237	  if (monitoring.metrics) {
238	    errors.push(...validateMonitoringMetrics(asArray(monitoring.metrics)));
239	  }
240	  if (monitoring.rollbackPlan) {
241	    if (!Array.isArray(monitoring.rollbackPlan.steps)) {
242	      errors.push({
243	        path: 'monitoring.rollbackPlan.steps',
244	        message: 'Rollback steps must be an array.'
245	      });
246	    } else if (!monitoring.rollbackPlan.steps.every(hasStringValue)) {
247	      errors.push({
248	        path: 'monitoring.rollbackPlan.steps',
249	        message: 'All rollback steps must be non-empty strings.'
250	      });
251	    }
252	  }
253	
254	  const audit = plan.audit ?? {};
255	  if (audit.artefacts) {
256	    if (!Array.isArray(audit.artefacts)) {
257	      errors.push({
258	        path: 'audit.artefacts',
259	        message: 'Artefacts must be an array of file references.'
260	      });
261	    } else if (!audit.artefacts.every(hasStringValue)) {
262	      errors.push({
263	        path: 'audit.artefacts',
264	        message: 'Artefact entries must be non-empty strings.'
265	      });
266	    }
267	  }
268	
269	  return {
270	    valid: errors.length === 0,
271	    errors
272	  };
273	}
